```apex
public class OrderPayloadParser {

    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body must not be empty.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }

        try {
            return buildOrder((Map<String, Object>) root);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Unable to parse order payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order must not be null.');
        }
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        Decimal totalValue = order.total == null ? Decimal.valueOf('0') : order.total;
        ack.put('total', totalValue);
        return JSON.serialize(ack);
    }

    private static Order buildOrder(Map<String, Object> root) {
        Order order = new Order();

        order.orderNumber = requireText(root, 'number');
        order.orderDate = parseDate(root.get('date'));
        order.currencyCode = asString(root.get('currency'));

        Object customer = root.get('customer');
        order.customerEmail = null;
        if (customer instanceof Map<String, Object>) {
            order.customerEmail = asString(((Map<String, Object>) customer).get('email'));
        }

        order.lines = new List<Line>();
        Object linesValue = root.get('lines');
        if (linesValue != null && !(linesValue instanceof List<Object>)) {
            throw new PayloadException('"lines" must be a JSON array.');
        }
        if (linesValue instanceof List<Object>) {
            for (Object item : (List<Object>) linesValue) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Each entry in "lines" must be a JSON object.');
                }
                order.lines.add(buildLine((Map<String, Object>) item));
            }
        }

        Decimal totalValue = 0;
        for (Line line : order.lines) {
            totalValue += line.lineTotal;
        }
        order.total = totalValue;

        return order;
    }

    private static Line buildLine(Map<String, Object> item) {
        Line line = new Line();

        line.sku = requireText(item, 'sku');

        Decimal quantityValue = asNumber(item.get('quantity'));
        if (quantityValue == null) {
            throw new PayloadException('Line "quantity" is required.');
        }
        if (quantityValue <= 0) {
            throw new PayloadException('Line "quantity" must be greater than zero.');
        }
        if (quantityValue != quantityValue.setScale(0, System.RoundingMode.DOWN)) {
            throw new PayloadException('Line "quantity" must be a whole number.');
        }
        line.quantity = quantityValue.intValue();

        Decimal unitPriceValue = asNumber(item.get('unitPrice'));
        if (unitPriceValue == null) {
            throw new PayloadException('Line "unitPrice" is required.');
        }
        if (unitPriceValue < 0) {
            throw new PayloadException('Line "unitPrice" must not be negative.');
        }
        line.unitPrice = unitPriceValue;

        Decimal discountValue = asNumber(item.get('discount'));
        line.discount = discountValue == null ? 0 : discountValue;

        line.lineTotal = (line.quantity * line.unitPrice * (1 - line.discount))
            .setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static String requireText(Map<String, Object> source, String key) {
        Object value = source.get(key);
        if (value == null || !(value instanceof String) || ((String) value).trim().length() == 0) {
            throw new PayloadException('"' + key + '" is required and must not be blank.');
        }
        return (String) value;
    }

    private static String asString(Object value) {
        return (value instanceof String) ? (String) value : null;
    }

    private static Decimal asNumber(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            Integer i = (Integer) value;
            Decimal d = i;
            return d;
        }
        if (value instanceof Long) {
            Long l = (Long) value;
            Decimal d = l;
            return d;
        }
        if (value instanceof Double) {
            return Decimal.valueOf(String.valueOf(value));
        }
        return null;
    }

    private static Date parseDate(Object value) {
        if (value == null || !(value instanceof String)) {
            return null;
        }
        String text = ((String) value).trim();
        if (text.length() == 0) {
            return null;
        }
        try {
            return Date.valueOf(text);
        } catch (Exception e) {
            throw new PayloadException('Invalid order date: ' + text);
        }
    }
}
