public with sharing class OpportunityWinService
{
	/**
	 * Marks the given opportunities as Closed Won and, for every opportunity this
	 * call actually closes, publishes one Deal_Won__e platform event.
	 *
	 * The record changes and the event publishing are both registered with a single
	 * fflib unit of work (Application.UnitOfWork) and committed exactly once, so
	 * Fulfilment is only ever told about a deal that has been saved. The events are
	 * registered with registerPublishAfterTransaction(), so nothing is published
	 * until the opportunity DML has succeeded - if saving fails, commitWork()
	 * rolls back and throws, no Deal_Won__e is published, and the exception
	 * propagates to the caller.
	 *
	 * @param opportunityIds ids of the opportunities to close
	 * @return the number of opportunities that were closed by this call (0 for null/empty input)
	 */
	public static Integer markWon(Set<Id> opportunityIds)
	{
		if (opportunityIds == null || opportunityIds.isEmpty())
		{
			return 0;
		}

		List<Opportunity> opportunities =
			OpportunitiesSelector.newInstance().selectById(opportunityIds);

		// Skip anything that is already Closed Won.
		List<Opportunity> opportunitiesToClose = new List<Opportunity>();
		if (opportunities != null)
		{
			for (Opportunity opportunity : opportunities)
			{
				if (opportunity.StageName != 'Closed Won')
				{
					opportunitiesToClose.add(opportunity);
				}
			}
		}

		if (opportunitiesToClose.isEmpty())
		{
			return 0;
		}

		fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
		Date today = Date.today();

		for (Opportunity opportunity : opportunitiesToClose)
		{
			opportunity.StageName = 'Closed Won';
			opportunity.CloseDate = today;

			// The opportunity update, registered with the unit of work.
			uow.registerDirty(opportunity);

			// One event per opportunity this call closes, published through the same
			// unit of work (never by calling EventBus.publish() directly) and only
			// after the transaction's DML has succeeded.
			uow.registerPublishAfterTransaction(
				new Deal_Won__e(
					Opportunity_Id__c = opportunity.Id,
					Amount__c = opportunity.Amount
				)
			);
		}

		// Single commit for the updates and the events; on failure the unit of work
		// rolls back, nothing is published and the exception propagates to the caller.
		uow.commitWork();

		return opportunitiesToClose.size();
	}
}
