/**
 * Stages web one-off gifts as NPSP Data Import records and processes them
 * through NPSP's own import engine (BDI) so that NPSP's contact matching,
 * household creation and donation processing rules are applied, and every
 * staged npsp__DataImport__c row is retained as the audit trail.
 */
public with sharing class GiftImportService {

    /** One gift received from the website integration. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for a single gift, in the same order as the input list. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /** NPSP's terminal success status on a processed Data Import row. */
    private static final String STATUS_IMPORTED = 'Imported';

    /** NPSP's donor designation meaning "donation belongs to Contact1". */
    private static final String DONOR_CONTACT1 = 'Contact1';

    /**
     * Imports the supplied gifts through NPSP's Data Importer.
     *
     * @param gifts the gifts to import; may be null or empty
     * @return one ImportResult per gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // The org's Data Import settings (hierarchy custom setting) drive NPSP's
        // matching and donation-processing behaviour. The configured defaults
        // match contacts on first name, last name and personal email and never
        // match an existing donation, so the staged rows below follow those
        // defaults and no override is applied.
        npsp__Data_Import_Settings__c importSettings = npsp__Data_Import_Settings__c.getOrgDefaults();
        if (importSettings == null) {
            importSettings = npsp__Data_Import_Settings__c.getDefaults();
        }
        if (importSettings == null) {
            importSettings = new npsp__Data_Import_Settings__c();
        }

        // One staged row per gift, in input order.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = (gift == null) ? null : gift.firstName,
                npsp__Contact1_Lastname__c = (gift == null) ? null : gift.lastName,
                npsp__Contact1_Personal_Email__c = (gift == null) ? null : gift.email,
                npsp__Donation_Amount__c = (gift == null) ? null : gift.amount,
                npsp__Donation_Date__c = (gift == null) ? null : gift.giftDate,
                npsp__Donation_Donor__c = DONOR_CONTACT1
            ));
        }

        // Process synchronously in this transaction with NPSP's Data Import API.
        // NPSP isolates row-level failures (Status = Failed + failure
        // information), so a rejected row never aborts the remaining rows.
        List<npsp__DataImport__c> processed;
        try {
            processed = npsp.DataImportService.runImport(staged);
        } catch (Exception ex) {
            // The whole batch was rejected by NPSP; report it per gift but keep
            // whatever staged rows were persisted as the audit trail.
            for (Integer i = 0; i < gifts.size(); i++) {
                results.add(buildFailure(null, ex.getMessage()));
            }
            return results;
        }

        Map<Id, npsp__DataImport__c> processedById = loadProcessedResults(staged, processed);

        for (Integer i = 0; i < gifts.size(); i++) {
            results.add(toImportResult(resolveRow(i, staged, processed, processedById)));
        }

        return results;
    }

    /**
     * Re-reads the processed Data Import rows so the status, imported records
     * and failure information reflect exactly what NPSP persisted.
     */
    private static Map<Id, npsp__DataImport__c> loadProcessedResults(
        List<npsp__DataImport__c> staged,
        List<npsp__DataImport__c> processed
    ) {
        Set<Id> rowIds = new Set<Id>();
        if (staged != null) {
            for (npsp__DataImport__c row : staged) {
                if (row != null && row.Id != null) {
                    rowIds.add(row.Id);
                }
            }
        }
        if (processed != null) {
            for (npsp__DataImport__c row : processed) {
                if (row != null && row.Id != null) {
                    rowIds.add(row.Id);
                }
            }
        }

        Map<Id, npsp__DataImport__c> byId = new Map<Id, npsp__DataImport__c>();
        if (rowIds.isEmpty()) {
            return byId;
        }

        for (npsp__DataImport__c row : [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
              FROM npsp__DataImport__c
             WHERE Id IN :rowIds
        ]) {
            byId.put(row.Id, row);
        }
        return byId;
    }

    /** Resolves the Data Import row that corresponds to the i-th input gift. */
    private static npsp__DataImport__c resolveRow(
        Integer index,
        List<npsp__DataImport__c> staged,
        List<npsp__DataImport__c> processed,
        Map<Id, npsp__DataImport__c> processedById
    ) {
        npsp__DataImport__c candidate;
        if (processed != null && index < processed.size()) {
            candidate = processed[index];
        }
        if (candidate == null && staged != null && index < staged.size()) {
            candidate = staged[index];
        }
        if (candidate == null) {
            return null;
        }
        if (candidate.Id != null && processedById.containsKey(candidate.Id)) {
            return processedById.get(candidate.Id);
        }
        return candidate;
    }

    /** Maps a processed Data Import row onto the public result shape. */
    private static ImportResult toImportResult(npsp__DataImport__c row) {
        ImportResult result = new ImportResult();

        if (row == null) {
            result.success = false;
            result.errorMessage = 'NPSP returned no result for this gift.';
            return result;
        }

        result.contactId = row.npsp__Contact1Imported__c;
        result.opportunityId = row.npsp__DonationImported__c;
        result.success = STATUS_IMPORTED.equals(row.npsp__Status__c);

        if (result.success) {
            result.errorMessage = null;
        } else if (String.isNotBlank(row.npsp__FailureInformation__c)) {
            result.errorMessage = row.npsp__FailureInformation__c;
        } else if (String.isBlank(row.npsp__Status__c)) {
            result.errorMessage = 'The gift was not imported by NPSP.';
        } else {
            result.errorMessage = 'NPSP status: ' + row.npsp__Status__c;
        }

        return result;
    }

    /** Builds a failed result, used only if NPSP's import call itself throws. */
    private static ImportResult buildFailure(Id contactId, String message) {
        ImportResult result = new ImportResult();
        result.success = false;
        result.contactId = contactId;
        result.errorMessage = message;
        return result;
    }
}
