public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new
     * record Ids in request order. All validation happens before any DML, so a
     * single bad request fails the whole call with RecurringGiftException and
     * nothing is written. Bulk safe: one insert statement and no SOQL, so 200
     * requests stay well inside governor limits.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> recurringDonationIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return recurringDonationIds;
        }

        // ---- Validate everything first, before any DML ----
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];

            if (request == null || request.contactId == null) {
                throw new RecurringGiftException(
                    'Request at index ' + i + ': a Contact Id is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException(
                    'Request at index ' + i + ': amount must be greater than zero.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Request at index ' + i + ': dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException(
                    'Request at index ' + i + ': startDate is required.');
            }
        }

        // ---- Build the Enhanced Recurring Donations ----
        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            // null or 0 installments => open-ended (no end date)
            Boolean isOpenEnded = (request.installments == null || request.installments == 0);
            Boolean useLastDayOfMonth = (request.dayOfMonth == 31);

            recurringDonations.add(new npe03__Recurring_Donation__c(
                // Donor
                npe03__Contact__c = request.contactId,
                npe03__Organization__c = null,

                // Installment amount
                npe03__Amount__c = request.amount,

                // Monthly schedule
                npe03__Installment_Period__c = 'Monthly',
                npsp__InstallmentFrequency__c = 'Monthly',

                // Open-ended vs. fixed length (legacy + Enhanced fields kept in step)
                npe03__Schedule_Type__c = isOpenEnded ? 'Open' : 'Fixed',
                npe03__Open_Ended_Status__c = isOpenEnded ? 'Open' : 'None',
                npe03__Installments__c = isOpenEnded ? null : request.installments,
                npsp__RecurringType__c = isOpenEnded ? 'Open' : 'Fixed',
                npsp__EndDate__c = null, // NPSP derives the end date for fixed schedules

                // Dates: first installment / schedule start
                npe03__Date_Established__c = request.startDate,
                npe03__Next_Payment_Date__c = request.startDate,
                npsp__StartDate__c = request.startDate,

                // Day of month; 31 => Enhanced Recurring Donations' last-day option.
                // 29 and 30 are stored literally as those days.
                npsp__Day_of_Month__c = request.dayOfMonth,
                npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth,

                // Status and payment method
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = request.paymentMethod
            ));
        }

        // ---- Single DML statement; NPSP's trigger creates the installments ----
        insert recurringDonations;

        // Ids come back in list order, which matches request order.
        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            recurringDonationIds.add(rd.Id);
        }
        return recurringDonationIds;
    }
}
