/**
 * Splits an Opportunity across General Accounting Units (GAUs) by percentage.
 *
 * Every allocation is stored with BOTH the amount and the percent of the split.
 * The percent is what keeps the allocation amount correct when the Opportunity
 * amount is corrected later: a $1,000 gift split 60/40 becomes $1,200/$800 when
 * the gift is corrected to $2,000, with no further code required here.
 *
 * All validation happens before the first DML statement. Any problem raises
 * GauAllocationService.AllocationException and leaves existing data untouched.
 */
public with sharing class GauAllocationService {

    /** Raised when the requested split cannot be applied. */
    public class AllocationException extends Exception {}

    /**
     * Replaces every existing GAU allocation of the Opportunity with one allocation
     * per map entry and returns the inserted allocations.
     *
     * @param opportunityId  the Opportunity being split
     * @param percentByGauId GAU Id -> percent (60 means 60%). A total below 100 is allowed.
     * @return the allocations as they were stored
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        /* ------------------------------------------------------------------ *
         * 1. Validate - nothing is written until everything below passes.     *
         * ------------------------------------------------------------------ */

        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A General Accounting Unit is required.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('The percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'The percentages total ' + totalPercent + '; they cannot be greater than 100.'
            );
        }

        Set<Id> gauIds = percentByGauId.keySet();

        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ];

        if (gaus.size() != gauIds.size()) {
            throw new AllocationException('One or more General Accounting Units do not exist.');
        }

        for (npsp__General_Accounting_Unit__c gau : gaus) {
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit "' + gau.Name + '" is not active.'
                );
            }
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' does not exist.');
        }

        Decimal opportunityAmount = opportunities[0].Amount;

        /* ------------------------------------------------------------------ *
         * 2. Replace the allocations (validate first, DML after).             *
         * ------------------------------------------------------------------ */

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations; // one statement - bulk safe
        }

        // Deterministic order so callers always receive the same result set.
        List<Id> orderedGauIds = new List<Id>(gauIds);
        orderedGauIds.sort();

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();

        for (Id gauId : orderedGauIds) {
            Decimal percent = percentByGauId.get(gauId);

            // The percent keeps the split correct when the Opportunity amount changes;
            // the amount reflects the split as it stands right now.
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = opportunityAmount == null ? null : (opportunityAmount * percent) / 100
            );

            allocations.add(allocation);
        }

        insert allocations; // one statement - bulk safe

        // Return the records exactly as they were stored (NPSP may complete them on save).
        Set<Id> allocationIds = new Map<Id, npsp__Allocation__c>(allocations).keySet();

        return [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c,
                   npsp__Amount__c, npsp__Percent__c
            FROM npsp__Allocation__c
            WHERE Id IN :allocationIds
            ORDER BY npsp__General_Accounting_Unit__c
        ];
    }
}
