```apex
/**
 * Service used by the event check-in app to register a family in one go.
 *
 * Everything happens in a single transaction so that a failure anywhere rolls
 * the whole call back - the org is never left with an empty/extra household.
 */
public with sharing class HouseholdService {

    /** NPSP DeveloperName of the Household Account record type. */
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    /**
     * Creates exactly one NPSP Household Account and places every member
     * Contact on it, with the first Contact as the household's primary contact.
     *
     * The household Account is inserted FIRST, carrying only the Household
     * record type. Its Name is deliberately left null: NPSP's automatic
     * household naming owns the Account name and the household greetings, and
     * it is re-evaluated when the members are attached and when the primary
     * contact is set below.
     *
     * @param members Contacts that make up the household. They must be new
     *                (no Id, no AccountId) and the list must not be empty.
     * @return the Id of the newly created household Account.
     * @throws IllegalArgumentException if members is null or empty, or if the
     *         Household Account record type cannot be resolved.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires at least one member Contact.'
            );
        }

        // One household account for the whole family - resolved by DeveloperName,
        // never by a hard-coded record type Id.
        Account household = new Account(RecordTypeId = getHouseholdRecordTypeId());
        insert household;

        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // NPSP stores a household's primary contact here; the first contact in
        // the list is the household's primary contact.
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }

    /**
     * Looks up the Id of the NPSP Household Account record type at runtime.
     *
     * @return the record type Id of the HH_Account Account record type.
     * @throws IllegalArgumentException if no such record type exists.
     */
    private static Id getHouseholdRecordTypeId() {
        List<RecordType> householdRecordTypes = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME
            LIMIT 1
        ];

        if (householdRecordTypes.isEmpty()) {
            throw new IllegalArgumentException(
                'No Account record type with DeveloperName "'
                + HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME
                + '" was found in this org.'
            );
        }

        return householdRecordTypes[0].Id;
    }
}
