/**
 * Service used by the student-system import to create NPSP family (parent/child) links.
 *
 * Limits contract for one call: at most 1 SOQL query and 1 DML statement of our own,
 * for any number of pairs (e.g. 200).
 *
 * Only the "Parent" side of each pair is written here. NPSP's own Relationship trigger
 * (TDTM) reacts to the insert, reads the npe4__Relationship_Lookup__c row for "Parent"
 * using the default "List Setting" reciprocal method, and creates the reciprocal record
 * (Son / Daughter / Child, chosen from the Male / Female / Neutral columns) while
 * stamping npe4__ReciprocalRelationship__c on both records. That is why no extra query
 * for the lookup setting or for contact gender is needed - NPSP does that work itself
 * (those extra queries/DML belong to NPSP, not to this class).
 */
public class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * Records that the value (parent Contact) is the Parent of the key (child Contact),
     * with status Current, so that:
     *  - the child's Relationships list shows the parent as "Parent", and
     *  - the parent's Relationships list shows the child as "Son", "Daughter" or "Child"
     *    according to NPSP's reciprocal lookup.
     *
     * Pairs that already have a relationship in either direction are skipped, so the
     * import can be re-run safely (idempotent).
     *
     * @param parentIdByChildId key = child Contact Id, value = parent Contact Id.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // Null or empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Normalise the input: drop null keys/values and self references, and collect
        // every contact that takes part in a pair (needed for the single query below).
        Map<Id, Id> cleanPairs = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            cleanPairs.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (cleanPairs.isEmpty()) {
            return;
        }

        // ---------------------------------------------------------------------------
        // Query 1 of 1: every relationship that already exists between these contacts.
        // Both endpoints are restricted to the same id set, so a relationship stored in
        // either direction (child -> parent or parent -> child) is returned by this
        // single query; no OR is required.
        // ---------------------------------------------------------------------------
        Set<String> existingRelationships = new Set<String>();

        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            // Store both orderings so either direction of an existing link is detected.
            existingRelationships.add(
                relationship.npe4__Contact__c + '|' + relationship.npe4__RelatedContact__c
            );
            existingRelationships.add(
                relationship.npe4__RelatedContact__c + '|' + relationship.npe4__Contact__c
            );
        }

        // ---------------------------------------------------------------------------
        // Build the "Parent" side of every pair that is not already linked.
        // ---------------------------------------------------------------------------
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : cleanPairs.keySet()) {
            Id parentId = cleanPairs.get(childId);

            // Skip pairs that already have a relationship in either direction.
            if (existingRelationships.contains(childId + '|' + parentId)) {
                continue;
            }

            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,          // child's list shows this record
                npe4__RelatedContact__c = parentId,  // ... and the related contact is the parent
                npe4__Type__c = TYPE_PARENT,         // "Parent"
                npe4__Status__c = STATUS_CURRENT     // "Current"
                // npe4__ReciprocalRelationship__c is left to NPSP: it fills in
                // Son / Daughter / Child from the Relationship Lookup list setting.
            ));
        }

        if (relationshipsToInsert.isEmpty()) {
            return;
        }

        // ---------------------------------------------------------------------------
        // DML 1 of 1: NPSP's Relationship trigger creates the reciprocal record for each
        // inserted row (Son / Daughter / Child for the parent's side) and links both
        // records via npe4__ReciprocalRelationship__c, so each pair ends up with exactly
        // one relationship record in each direction.
        // ---------------------------------------------------------------------------
        insert relationshipsToInsert;
    }
}
