/**
 * NPSP Table-Driven Trigger Management (TDTM) handler that opens a follow-up
 * task for every newly closed major gift.
 *
 * Admin registration (NPSP Settings > Trigger Configuration):
 *   Class          : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Asynchronous   : No
 *
 * There is deliberately NO Apex trigger in this package: NPSP's TDTM dispatcher
 * is the only caller, so switching off the Trigger Handler record switches this
 * automation off for the whole org.
 *
 * Limits honoured by this handler for the whole batch in one transaction:
 *   - SOQL queries   : 0  (it reads only the records the dispatcher hands it,
 *                          so trigger-context fields such as Amount,
 *                          StageName, IsWon, CloseDate, OwnerId and
 *                          npsp__Primary_Contact__c are already present)
 *   - DML statements : 1  (a single bulk insert of every follow-up Task)
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;
    private static final String FOLLOW_UP_SUBJECT = 'Major gift thank-you call';
    private static final String FOLLOW_UP_PRIORITY = 'High';
    private static final String FOLLOW_UP_STATUS = 'Not Started';
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    /**
     * Entry point invoked by NPSP's TDTM dispatcher for the registered
     * AfterInsert / AfterUpdate actions on Opportunity.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // ---- Guard rails: only handle what we were registered for ---------
        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }
        if (objResult != null && objResult.getSObjectType() != Opportunity.SObjectType) {
            return dmlWrapper;
        }
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
                && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        List<Opportunity> newOpps = toOpportunities(newlist);
        if (newOpps.isEmpty()) {
            return dmlWrapper;
        }
        // "old" rows are null on insert; on update they carry the pre-edit values.
        List<Opportunity> oldOpps = toOpportunities(oldlist);

        // Old values can be resolved by Id (robust) or by position (records
        // built in memory without Ids).
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (Opportunity oldOpp : oldOpps) {
            if (oldOpp != null && oldOpp.Id != null) {
                oldById.put(oldOpp.Id, oldOpp);
            }
        }

        Set<Id> alreadyQueuedOppIds = new Set<Id>();
        List<Task> followUps = new List<Task>();

        for (Integer index = 0; index < newOpps.size(); index++) {
            Opportunity newOpp = newOpps[index];
            if (newOpp == null) {
                continue;
            }
            // Never queue the same opportunity twice inside one batch.
            if (newOpp.Id != null && alreadyQueuedOppIds.contains(newOpp.Id)) {
                continue;
            }

            // (1) It must be a major gift right now: Closed Won + Amount >= 5,000.
            if (!isMajorGift(newOpp)) {
                continue;
            }

            // (2) On update it must NOT already have been a major gift before,
            //     otherwise this is just an edit of a gift that already
            //     qualified and no second task may be created.
            if (isUpdate) {
                Opportunity oldOpp = null;
                if (newOpp.Id != null && oldById.containsKey(newOpp.Id)) {
                    oldOpp = oldById.get(newOpp.Id);
                } else if (index < oldOpps.size()) {
                    oldOpp = oldOpps[index];
                }
                if (isMajorGift(oldOpp)) {
                    continue;
                }
            }

            if (newOpp.Id != null) {
                alreadyQueuedOppIds.add(newOpp.Id);
            }
            followUps.add(buildFollowUpTask(newOpp));
        }

        // ---- ONE bulk DML statement for the whole trigger batch -----------
        if (!followUps.isEmpty()) {
            insert followUps;
        }

        return dmlWrapper;
    }

    /**
     * A major gift is an opportunity that is Closed Won and has an Amount of at
     * least 5,000. Null-safe: a record that is missing a value (including a
     * missing "old" record) simply does not qualify as "qualified before".
     */
    private static Boolean isMajorGift(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        if (opp.Amount == null || opp.Amount < MAJOR_GIFT_AMOUNT) {
            return false;
        }
        return isClosedWon(opp);
    }

    /**
     * "Closed Won" is recognised either from the standard IsWon flag (populated
     * by the platform in trigger context) or from the stage label, so stage
     * names and casing variations are handled without needing a SOQL query on
     * the OpportunityStage table.
     */
    private static Boolean isClosedWon(Opportunity opp) {
        if (opp.IsWon) {
            return true;
        }
        String stage = opp.StageName;
        if (String.isBlank(stage)) {
            return false;
        }
        return CLOSED_WON_STAGE.equalsIgnoreCase(stage.trim());
    }

    /**
     * Builds the single follow-up task for a newly qualified major gift.
     */
    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task();
        followUp.Subject = FOLLOW_UP_SUBJECT;
        followUp.Priority = FOLLOW_UP_PRIORITY;
        followUp.Status = FOLLOW_UP_STATUS;
        followUp.WhatId = opp.Id;
        followUp.WhoId = opp.npsp__Primary_Contact__c;   // may be null
        followUp.OwnerId = opp.OwnerId;                  // the opportunity owner
        followUp.ActivityDate = (opp.CloseDate == null)
            ? null
            : opp.CloseDate.addDays(FOLLOW_UP_OFFSET_DAYS);  // CloseDate + 3 days
        return followUp;
    }

    /**
     * Defensive cast of the lists the dispatcher passes in.
     */
    private static List<Opportunity> toOpportunities(List<SObject> records) {
        List<Opportunity> opps = new List<Opportunity>();
        if (records == null || records.isEmpty()) {
            return opps;
        }
        for (SObject record : records) {
            if (record instanceof Opportunity) {
                opps.add((Opportunity) record);
            }
        }
        return opps;
    }
}
