/**
 * Trigger record used by the Trigger Actions Framework (TAF) when it evaluates
 * Trigger_Action__mdt.Entry_Criteria__c for Account actions.
 *
 * TAF instantiates this class (named in
 * sObject_Trigger_Setting__mdt.TriggerRecord_Class_Name__c), populates the
 * inherited newSobject / oldSobject values for the record being processed, and
 * then evaluates the entry criteria formula against it.
 *
 * The typed accessors below expose the new and the previous Account value so
 * that entry criteria can reference them, e.g.:
 *
 *   newRecord.Rating = 'Hot' AND oldRecord.Rating != 'Hot'
 *
 * The class is shared by every Account action. Actions with a blank
 * Entry_Criteria__c are unaffected by it, so inserts and unrelated updates keep
 * behaving exactly as before.
 */
public class AccountTriggerRecord extends TriggerRecord {
	public Account newRecord {
		get {
			return (Account) newSobject;
		}
		set {
			newSobject = value;
		}
	}

	public Account oldRecord {
		get {
			return (Account) oldSobject;
		}
		set {
			oldSobject = value;
		}
	}
}
