/**
 * Before insert: a new Contact that has an Account and a completely blank
 * mailing address inherits the Account's billing address. A Contact that
 * already carries any mailing address value keeps its own address.
 * Contacts without an Account are left untouched.
 * Performs no SOQL - it reads the Accounts loaded by TA_Contact_Queries.Service.
 */
public inherited sharing class TA_Contact_InheritMailingAddress
		implements TriggerAction.BeforeInsert {
	public void beforeInsert(List<SObject> triggerNew) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
		if (accountsById == null) {
			return;
		}
		for (SObject record : triggerNew) {
			Contact newContact = (Contact) record;
			if (newContact.AccountId == null) {
				continue;
			}
			Account parentAccount = accountsById.get(newContact.AccountId);
			if (parentAccount == null) {
				continue;
			}
			if (
				String.isBlank(newContact.MailingStreet) &&
				String.isBlank(newContact.MailingCity) &&
				String.isBlank(newContact.MailingPostalCode) &&
				String.isBlank(newContact.MailingCountry)
			) {
				newContact.MailingStreet = parentAccount.BillingStreet;
				newContact.MailingCity = parentAccount.BillingCity;
				newContact.MailingPostalCode = parentAccount.BillingPostalCode;
				newContact.MailingCountry = parentAccount.BillingCountry;
			}
		}
	}
}
